import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

depthwise_pointwise_conv2d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// -----------------------------------------
// Naive depthwise convolution kernel
// -----------------------------------------
__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ depthwise_weight,
    float* __restrict__ output,
    int batch_size, int in_channels,
    int in_height, int in_width,
    int kernel_size, int stride,
    int padding, int dilation,
    int out_height, int out_width
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * in_channels * out_height * out_width;
    if (index >= total) return;

    // Compute n, c, h_out, w_out
    int w_out = index % out_width;
    int t = index / out_width;
    int h_out = t % out_height;
    t /= out_height;
    int c = t % in_channels;
    int n = t / in_channels;

    // Compute input base index
    int out_idx = n * in_channels * out_height * out_width
                  + c * out_height * out_width
                  + h_out * out_width
                  + w_out;

    float val = 0.0f;

    // (h_out, w_out) in output => for each weight location (kh, kw)
    int h_in0 = h_out * stride - padding;
    int w_in0 = w_out * stride - padding;

    for (int kh = 0; kh < kernel_size; kh++) {
        for (int kw = 0; kw < kernel_size; kw++) {
            int h_in = h_in0 + kh * dilation;
            int w_in = w_in0 + kw * dilation;
            if (h_in >= 0 && h_in < in_height && w_in >= 0 && w_in < in_width) {
                int in_idx = n * in_channels * in_height * in_width
                             + c * in_height * in_width
                             + h_in * in_width
                             + w_in;
                int w_idx = c * kernel_size * kernel_size + kh * kernel_size + kw;
                val += input[in_idx] * depthwise_weight[w_idx];
            }
        }
    }
    output[out_idx] = val;
}

// -----------------------------------------
// Naive pointwise convolution kernel
// -----------------------------------------
__global__ void pointwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ pointwise_weight,
    float* __restrict__ output,
    int batch_size, int in_channels, int out_channels,
    int height, int width
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * out_channels * height * width;
    if (index >= total) return;

    // Compute n, c_out, h, w
    int w_out = index % width;
    int t = index / width;
    int h_out = t % height;
    t /= height;
    int c_out = t % out_channels;
    int n = t / out_channels;

    // Output index
    int out_idx = n * out_channels * height * width
                  + c_out * height * width
                  + h_out * width
                  + w_out;

    float val = 0.0f;
    // Sum over in_channels
    for (int c_in = 0; c_in < in_channels; c_in++) {
        int in_idx = n * in_channels * height * width
                     + c_in * height * width
                     + h_out * width
                     + w_out;
        // pointwise_weight shape [out_channels, in_channels, 1, 1]
        int w_idx = c_out * in_channels + c_in;
        val += input[in_idx] * pointwise_weight[w_idx];
    }
    output[out_idx] = val;
}

// -----------------------------------------
// Depthwise convolution (wrapper)
// -----------------------------------------
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor depthwise_weight,
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_height = input.size(2);
    int in_width = input.size(3);

    int out_height = (in_height + 2*padding - dilation*(kernel_size-1) - 1) / stride + 1;
    int out_width  = (in_width + 2*padding - dilation*(kernel_size-1) - 1) / stride + 1;

    auto out = torch::zeros({batch_size, in_channels, out_height, out_width}, input.options());

    int total = batch_size * in_channels * out_height * out_width;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    depthwise_conv2d_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        depthwise_weight.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size, in_channels,
        in_height, in_width,
        kernel_size, stride,
        padding, dilation,
        out_height, out_width
    );
    return out;
}

// -----------------------------------------
// Pointwise convolution (wrapper)
// -----------------------------------------
torch::Tensor pointwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor pointwise_weight,
    int out_channels
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);

    auto out = torch::zeros({batch_size, out_channels, height, width}, input.options());

    int total = batch_size * out_channels * height * width;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    pointwise_conv2d_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(),
        pointwise_weight.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        height, width
    );
    return out;
}
"""

depthwise_pointwise_conv2d_cpp_source = r"""
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor depthwise_weight,
    int kernel_size,
    int stride,
    int padding,
    int dilation
);

torch::Tensor pointwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor pointwise_weight,
    int out_channels
);
"""

dp_conv = load_inline(
    name="depthwise_pointwise_conv2d",
    cpp_sources=[depthwise_pointwise_conv2d_cpp_source],
    cuda_sources=[depthwise_pointwise_conv2d_source],
    functions=["depthwise_conv2d_cuda", "pointwise_conv2d_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.bias = bias

        # Depthwise conv weights: [in_channels, 1, kernel_size, kernel_size]
        # We'll store them in a Parameter for training (bias not used here).
        dw_shape = (in_channels, 1, kernel_size, kernel_size)
        self.depthwise_weight = nn.Parameter(torch.randn(dw_shape))

        # Pointwise conv weights: [out_channels, in_channels, 1, 1]
        pw_shape = (out_channels, in_channels, 1, 1)
        self.pointwise_weight = nn.Parameter(torch.randn(pw_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        dw_out = dp_conv.depthwise_conv2d_cuda(
            x, self.depthwise_weight,
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation
        )
        pw_out = dp_conv.pointwise_conv2d_cuda(
            dw_out,
            self.pointwise_weight,
            self.out_channels
        )
        return pw_out
